import { v4 } from 'uuid';
// import {  } from 'systeminformation';
import { execSync } from 'node:child_process';
import temporaryDirectory from 'tmp';
import { join } from 'path';
import fs from 'fs-extra';

export type BundleResults = {
  bundleFiles: {
    system: 'windows' | 'macos' | 'linux';
    bundlePath: string;
  }[];
};
export type Options = {
  outPutRootDir?: string;
  outPutFileName?: string;
};

/** TODO: need to handle windows and linux */

export class SingleExecutableApplications {
  constructor(private options: Options) {}

  private bundleName = 'bundled-app';

  private outPutBlob = 'app.blob';

  private configFile = 'sea-config.json';

  async bundle(file: string): Promise<BundleResults> {
    const tmpWorkSpace = await this.createTmpDir();
    const config = this.getConfig(file, tmpWorkSpace);
    const configPath = join(tmpWorkSpace, this.configFile);

    await fs.writeJson(configPath, config);
    await this.buildMacOS(configPath, tmpWorkSpace);
    const bundlePath = this.getOutPutPath(tmpWorkSpace);
    return { bundleFiles: [{ system: 'macos', bundlePath }] };
  }

  private getOutPutPath(tmpWorkSpace: string) {
    const outPutFile = join(tmpWorkSpace, this.bundleName);
    if (this.options.outPutRootDir) {
      const dest = join(
        this.options.outPutRootDir,
        this.options.outPutFileName || this.bundleName
      );
      fs.moveSync(outPutFile, dest, { overwrite: true });
      return dest;
    }
    return outPutFile;
  }

  private async buildMacOS(configPath: string, cwd: string) {
    const execOptions = {
      cwd,
    };
    execSync(`node --experimental-sea-config ${configPath}`, execOptions);
    execSync(`cp "$(command -v node)" ${this.bundleName}`, execOptions);
    execSync(`codesign --remove-signature ${this.bundleName}`, execOptions);
    execSync(
      `npx postject ${this.bundleName} NODE_SEA_BLOB ${this.outPutBlob} --sentinel-fuse NODE_SEA_FUSE_fce680ab2cc467b6e072b8b5df1996b2 --macho-segment-name NODE_SEA`,
      execOptions
    );
    execSync(`codesign --sign - ${this.bundleName}`, execOptions);
  }

  getConfig(mainFile: string, dir: string) {
    return {
      main: mainFile,
      // TODO: check if it work at windows!
      output: join(dir, this.outPutBlob),
      disableExperimentalSEAWarning: true, // Default: false
      useSnapshot: false, // Default: false
      useCodeCache: true, // Default: false
    };
  }

  private async createTmpDir() {
    const tmpPath = temporaryDirectory.dirSync({ name: v4() }).name;
    return tmpPath;
  }
}
